def is_valid_self_closing_mix(s):
    import re
    pos = 0
    stack = []
    pattern = re.compile(r'<([a-z]+)/>|<([a-z]+)>|</([a-z]+)>')
    while pos < len(s):
        m = pattern.match(s, pos)
        if not m:
            return False
        if m.group(1) is not None:
            pass
        elif m.group(2) is not None:
            stack.append(m.group(2))
        else:
            if not stack or stack[-1] != m.group(3):
                return False
            stack.pop()
        pos = m.end()
    return len(stack) == 0

def sliding_window_average(lst, k):
    if k <= 0 or k > len(lst):
        return []
    return [round(sum(lst[i:i+k]) / k, 4) for i in range(len(lst) - k + 1)]

def chunk_by_predicate_change(lst):
    if not lst:
        return []
    out = []
    current = [lst[0]]
    prev_even = lst[0] % 2 == 0
    for x in lst[1:]:
        even = x % 2 == 0
        if even == prev_even:
            current.append(x)
        else:
            out.append(current)
            current = [x]
            prev_even = even
    out.append(current)
    return out

def is_valid_run_length_encoding(s):
    import re
    if not s:
        return False
    groups = re.findall(r'\d+[A-Za-z]|.', s)
    for g in groups:
        if not re.fullmatch(r'\d+[A-Za-z]', g):
            return False
        count = g[:-1]
        if len(count) > 1 and count[0] == '0':
            return False
        if int(count) == 0:
            return False
    return True

def is_valid_pin_code(s):
    if len(s) != 4 or not s.isdigit():
        return False
    digits = [int(c) for c in s]
    if len(set(digits)) == 1:
        return False
    if all(digits[i] + 1 == digits[i + 1] for i in range(3)):
        return False
    if all(digits[i] - 1 == digits[i + 1] for i in range(3)):
        return False
    return True

def invert_filtered_positive(d):
