def percentile_of_value_among_duplicates(scores, value):
    less = sum(1 for s in scores if s < value)
    equal = sum(1 for s in scores if s == value)
    return round((less + 0.5 * equal) / len(scores) * 100, 2)

def digit_frequency(nums):
    counts = {}
    for n in nums:
        for ch in str(abs(n)):
            counts[ch] = counts.get(ch, 0) + 1
    return counts

def render_row_truncate_pad(cells, widths):
    parts = []
    for c, w in zip(cells, widths):
        if len(c) > w:
            parts.append(c[:w])
        else:
            parts.append(c.ljust(w))
    return " ".join(parts)

def flatten_dict_tuple_keys(d):
    result = {}
    for k, v in d.items():
        if isinstance(v, dict) and v:
            for nk, nv in flatten_dict_tuple_keys(v).items():
                result[(k,) + nk] = nv
        else:
            result[(k,)] = v
    return result

def unflatten_dict(flat, sep):
    result = {}
    for key, value in flat.items():
        parts = key.split(sep)
        d = result
        for p in parts[:-1]:
            d = d.setdefault(p, {})
        d[parts[-1]] = value
    return result

def min_max_across_dicts(records):
    mins = {}
    maxs = {}
    for r in records:
        for k, v in r.items():
            if k not in mins or v < mins[k]:
                mins[k] = v
            if k not in maxs or v > maxs[k]:
                maxs[k] = v
    return {k: (mins[k], maxs[k]) for k in mins}

