def most_common_first_occurrence(items):
    counts = {}
    for x in items:
        counts[x] = counts.get(x, 0) + 1
    best = max(counts.values())
    for x in items:
        if counts[x] == best:
            return x

def dict_average_values(list_of_dicts):
    sums = {}
    counts = {}
    for d in list_of_dicts:
        for k, v in d.items():
            sums[k] = sums.get(k, 0) + v
            counts[k] = counts.get(k, 0) + 1
    return {k: sums[k] / counts[k] for k in sums}

def pad_iso_date(s):
