def is_valid_ipv6_full(s):
    groups = s.split(':')
    if len(groups) != 8:
        return False
    hexdigits = set('0123456789abcdefABCDEF')
    for g in groups:
        if not (1 <= len(g) <= 4):
            return False
        if not all(c in hexdigits for c in g):
            return False
    return True

def top_word_per_length(text):
    words = text.split()
    groups = {}
    for w in words:
        groups.setdefault(len(w), []).append(w)
    res = {}
    for l, ws in groups.items():
        c = {}
        for w in ws:
            c[w] = c.get(w, 0) + 1
        best = max(c.values())
        cands = sorted(w for w, cnt in c.items() if cnt == best)
        res[l] = cands[0]
    return res

def is_unimodal(lst):
    n = len(lst)
    if n < 3:
        return False
    i = 0
    while i + 1 < n and lst[i] < lst[i + 1]:
        i += 1
    if i == 0 or i == n - 1:
        return False
    while i + 1 < n and lst[i] > lst[i + 1]:
        i += 1
    return i == n - 1
